// UsdGeomHermiteCurves — cubic Hermite-interpolated curves (points + tangents).
// Reference: pxr/usd/usdGeom/hermiteCurves.h / hermiteCurves.cpp.
//
// The schema carries `curveVertexCounts`, `points` (PointBased) and a parallel
// `tangents` array. The nested `PointAndTangentArrays` value type is the
// serialization helper that interleaves/separates the two parallel arrays the
// way upstream packs them on the wire ([p0, t0, p1, t1, ...]).




type Vec3 = [number, number, number]

function asVec3(v: readonly number[]): Vec3 {
  return [Number(v[0] ?? 0), Number(v[1] ?? 0), Number(v[2] ?? 0)]
}

function vec3Equal(a: Vec3, b: Vec3): boolean {
  return a[0] === b[0] && a[1] === b[1] && a[2] === b[2]
}

// UsdGeomHermiteCurves::PointAndTangentArrays — parallel point/tangent arrays
// with the on-wire interleaving helpers.
export class PointAndTangentArrays {
  private readonly _points: Vec3[]
  private readonly _tangents: Vec3[]

  constructor(points: readonly (readonly number[])[] = [], tangents: readonly (readonly number[])[] = []) {
    if (points.length !== tangents.length) {
      // Mirrors the TF_CODING_ERROR / Tf.ErrorException upstream raises when
      // the two parallel arrays disagree in length.
      throw new Error(
        `UsdGeomHermiteCurves.PointAndTangentArrays: points (${points.length}) and ` +
        `tangents (${tangents.length}) must have the same length`)
    }
    this._points = points.map(asVec3)
    this._tangents = tangents.map(asVec3)
  }

  getPoints(): Vec3[] { return this._points.map((p) => [...p] as Vec3) }
  getTangents(): Vec3[] { return this._tangents.map((t) => [...t] as Vec3) }

  isEmpty(): boolean { return this._points.length === 0 }

  // Truthiness: a populated array is "true", an empty one "false" (operator bool).
  get valid(): boolean { return !this.isEmpty() }

  equals(other: PointAndTangentArrays): boolean {
    if (this._points.length !== other._points.length) return false
    for (let i = 0; i < this._points.length; i++) {
      if (!vec3Equal(this._points[i]!, other._points[i]!)) return false
      if (!vec3Equal(this._tangents[i]!, other._tangents[i]!)) return false
    }
    return true
  }

  // [p0, t0, p1, t1, ...] — the packed wire layout (Interleave()).
  interleave(): Vec3[] {
    if (this.isEmpty()) return []
    const out: Vec3[] = []
    for (let i = 0; i < this._points.length; i++) {
      out.push([...this._points[i]!] as Vec3)
      out.push([...this._tangents[i]!] as Vec3)
    }
    return out
  }

  // Inverse of interleave(); the interleaved array must have even length.
  static separate(interleaved: readonly (readonly number[])[]): PointAndTangentArrays {
    if (interleaved.length % 2 !== 0) {
      throw new Error(
        `UsdGeomHermiteCurves.PointAndTangentArrays.Separate: interleaved array length ` +
        `${interleaved.length} must be even`)
    }
    const points: Vec3[] = []
    const tangents: Vec3[] = []
    for (let i = 0; i < interleaved.length; i += 2) {
      points.push(asVec3(interleaved[i]!))
      tangents.push(asVec3(interleaved[i + 1]!))
    }
    return new PointAndTangentArrays(points, tangents)
  }
}

